-- Additive only. Legacy timestamps/seen keys/items and financial budgets are retained.
ALTER TABLE stock_news_state ADD COLUMN last_attempt_at DATETIME(3) NULL, ADD COLUMN last_finished_at DATETIME(3) NULL, ADD COLUMN last_full_success_at DATETIME(3) NULL, ADD COLUMN last_new_stored_at DATETIME(3) NULL;
ALTER TABLE stock_news_provider_state ADD COLUMN slot_key VARCHAR(100) NULL, ADD COLUMN status VARCHAR(20) NOT NULL DEFAULT 'NOT_COLLECTED', ADD COLUMN attempts TINYINT UNSIGNED NOT NULL DEFAULT 0, ADD COLUMN next_retry_at DATETIME(3) NULL, ADD COLUMN last_checked_at DATETIME(3) NULL, ADD COLUMN gaps JSON NULL, ADD COLUMN diagnostics JSON NULL;
ALTER TABLE stock_news_seen ADD COLUMN status VARCHAR(24) NOT NULL DEFAULT 'LEGACY_UNKNOWN', ADD COLUMN reason VARCHAR(120) NULL, ADD COLUMN last_checked_at DATETIME(3) NULL, ADD INDEX stock_news_seen_review_idx(status,first_seen_at);
CREATE TABLE stock_news_schedule (id VARCHAR(40) NOT NULL PRIMARY KEY,interval_hours TINYINT UNSIGNED NOT NULL DEFAULT 3,start_time CHAR(5) NOT NULL DEFAULT '06:00',anchor_at DATETIME(3) NOT NULL,revision INT UNSIGNED NOT NULL DEFAULT 1,updated_at DATETIME(3) NOT NULL) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE stock_news_slots (`key` VARCHAR(100) NOT NULL PRIMARY KEY,kind VARCHAR(16) NOT NULL,scheduled_at DATETIME(3) NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'RUNNING',attempts TINYINT UNSIGNED NOT NULL DEFAULT 0,next_retry_at DATETIME(3) NULL,started_at DATETIME(3) NOT NULL,finished_at DATETIME(3) NULL,INDEX(scheduled_at)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE stock_news_candidates (canonical_hash CHAR(64) NOT NULL PRIMARY KEY,fingerprint CHAR(64) NOT NULL,provider VARCHAR(40) NOT NULL,provider_id VARCHAR(160) NOT NULL,payload JSON NOT NULL,priority TINYINT UNSIGNED NOT NULL,published_at DATETIME(3) NOT NULL,expires_at DATETIME(3) NOT NULL,status VARCHAR(24) NOT NULL,reason VARCHAR(120) NULL,first_seen_at DATETIME(3) NOT NULL,last_checked_at DATETIME(3) NOT NULL,INDEX stock_news_candidate_queue_idx(status,expires_at,priority,published_at),INDEX(first_seen_at)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
-- Do not infer a full-success time from PARTIAL legacy records.
UPDATE stock_news_state s SET last_new_stored_at=(SELECT MAX(collected_at) FROM stock_news_items),last_finished_at=last_collected_at;
